#![no_std]
use super::core::{AndroidDriverAdapter,CoreError,DriverAdapter,DriverSlot,HardwareInfo,AdapterState};
use super::universal::{DriverAbi,DriverOs};
pub struct AndroidLayer<A>{pub slot:DriverSlot<A>}
impl<A:AndroidDriverAdapter>AndroidLayer<A>{pub const fn new(adapter:A)->Self{Self{slot:DriverSlot::new(adapter)}}pub fn validate(&self,hw:&HardwareInfo)->Result<(),CoreError>{let id=self.slot.adapter.identity();if id.os!=DriverOs::Android||id.abi!=DriverAbi::AndroidHal{return Err(CoreError::UnsupportedAbi)}let api=self.slot.adapter.android_hal_version();if id.api_version==0||api==0||api>u32::from(u16::MAX)||id.api_version!=api as u16{return Err(CoreError::InvalidRequest)}let name=self.slot.adapter.android_interface_name();if name.len()<3||!name.as_bytes().iter().any(|b|*b==b'/'){return Err(CoreError::InvalidRequest)}if !id.matches(hw)||!hw.valid()||hw.irq==u32::MAX{return Err(CoreError::InvalidDevice)}Ok(())}pub fn can_probe(&self,hw:&HardwareInfo)->bool{self.validate(hw).is_ok()&&self.slot.state==AdapterState::New}}
#[cfg(test)]mod tests{use super::*;use super::super::bus::DeviceId;struct Mock{api:u32,name:&'static str,os:DriverOs,abi:DriverAbi,vendor:u16,device:u16,signed:bool}impl DriverAdapter for Mock{fn identity(&self)->super::super::core::DriverIdentity{super::super::core::DriverIdentity{os:self.os,abi:self.abi,api_version:self.api as u16,vendor:self.vendor,device:self.device,signed:self.signed}}fn probe(&mut self,_:&HardwareInfo)->Result<(),CoreError>{Ok(())}fn start(&mut self,_:&HardwareInfo)->Result<(),CoreError>{Ok(())}fn stop(&mut self,_:&HardwareInfo)->Result<(),CoreError>{Ok(())}fn remove(&mut self,_:&HardwareInfo)->Result<(),CoreError>{Ok(())}}impl AndroidDriverAdapter for Mock{fn android_hal_version(&self)->u32{self.api}fn android_interface_name(&self)->&'static str{self.name}}fn hw()->HardwareInfo{HardwareInfo{id:DeviceId{vendor:1,device:2,class:0,revision:1},mmio_base:0x1000,mmio_length:0x100,irq:5,dma_bits:64}}fn good()->AndroidLayer<Mock>{AndroidLayer::new(Mock{api:7,name:"vendor/awe-hal",os:DriverOs::Android,abi:DriverAbi::AndroidHal,vendor:1,device:2,signed:true})}#[test]fn probe_requires_new_state(){let x=good();assert!(x.can_probe(&hw()));}}
